#!/usr/bin/env node
'use strict';
/**
 * Regenerates src/renderer/icons.js from the Lucide icon set (ISC license, https://lucide.dev).
 * Only needed when you add an icon to the list below:  npm i --no-save lucide-static && node scripts/build-icons.js
 * The generated file is committed, so the app itself has no icon dependency and never touches the network.
 */
const fs = require('node:fs');
const path = require('node:path');

const NAMES = [
  'layout-dashboard', 'list-ordered', 'trophy', 'folder', 'folder-open', 'file', 'file-code', 'file-json', 'file-text', 'file-cog', 'file-terminal', 'image', 'lock',
  'git-branch', 'git-merge', 'git-compare', 'git-pull-request-arrow', 'plus', 'minus', 'x', 'check', 'check-check',
  'play', 'fast-forward', 'square', 'sparkles', 'sun', 'moon', 'settings', 'refresh-cw', 'files', 'search', 'bot',
  'scroll-text', 'chevron-right', 'chevron-down', 'chevron-left', 'circle-alert', 'triangle-alert', 'info',
  'circle-check', 'undo-2', 'terminal', 'square-terminal', 'trash-2', 'eye', 'clipboard-copy', 'send', 'copy',
  'list-checks', 'stethoscope', 'message-square-plus', 'globe', 'shield-check', 'history', 'git-commit-horizontal', 'archive', 'archive-restore', 'tag', 'git-pull-request', 'external-link', 'flask-conical', 'bell', 'repeat', 'command', 'link', 'user', 'bug', 'timer', 'cpu', 'package', 'workflow', 'arrow-up', 'arrow-down', 'database', 'braces', 'coffee', 'hash', 'download', 'upload-cloud', 'replace-all', 'unlock', 'play-circle', 'pause', 'skip-back', 'skip-forward', 'rewind', 'git-compare-arrows', 'palette',
  'box', 'square-function', 'octagon-pause', 'step-forward', 'corner-down-right', 'variable', 'layers', 'circle-dot', 'text-cursor-input',
];

let dir;
try { dir = path.dirname(require.resolve('lucide-static/package.json')) + '/icons'; } catch { console.error('Run: npm i --no-save lucide-static'); process.exit(1); }

const out = {};
for (const n of NAMES) {
  const file = path.join(dir, `${n}.svg`);
  if (!fs.existsSync(file)) { console.error(`Missing icon: ${n}`); process.exit(1); }
  const svg = fs.readFileSync(file, 'utf8');
  out[n] = svg.slice(svg.indexOf('>', svg.indexOf('<svg')) + 1, svg.lastIndexOf('</svg>')).replace(/\s+/g, ' ').trim();
}
const src = `'use strict';
/* GENERATED by scripts/build-icons.js from Lucide (ISC license, https://lucide.dev). Do not edit by hand. */
(function () {
  const PATHS = ${JSON.stringify(out, null, 2)};
  /** An inline <svg> that inherits the text colour (stroke: currentColor), so it follows the light/dark theme. */
  window.icon = function icon(name, cls) {
    if (!PATHS[name]) window.icon.missing.push(name); // surfaced by the smoke test, so a typo can't ship as an empty box
    const span = document.createElement('span');
    span.className = 'i' + (cls ? ' ' + cls : '');
    span.setAttribute('aria-hidden', 'true');
    span.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + (PATHS[name] || '') + '</svg>';
    return span;
  };
  window.icon.names = Object.keys(PATHS);
  window.icon.missing = [];
})();
`;
fs.writeFileSync(path.join(__dirname, '../src/renderer/icons.js'), src);
console.log(`icons.js: ${NAMES.length} icons, ${src.length} bytes`);
